	if v, ok := c.Get(1); !ok || v != 100 {
		t.Fatalf("Get(1) = (%d, %v), want (100, true)", v, ok)
	}
	// Insert a new key: key 2 is now the least recently used and must go.
	c.Put(3, 300)
	if _, ok := c.Get(2); ok {
		t.Errorf("key 2 still present after inserting 3; Get should have refreshed key 1's recency")
	}
	if v, ok := c.Get(1); !ok || v != 100 {
		t.Errorf("Get(1) = (%d, %v), want (100, true)", v, ok)
	}
	if v, ok := c.Get(3); !ok || v != 300 {
		t.Errorf("Get(3) = (%d, %v), want (300, true)", v, ok)
	}
}

