package lru

// Temporary verification tests for the LRU eviction fix.
// These reproduce the reported defects and must fail before the fix.

func TestGetMarksKeyRecentlyUsed(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 100)
	c.Put(2, 200)
	// Read key 1 so it becomes most recently used.
	if v, ok := c.Get(1); !ok || v != 100 {
		t.Fatalf("Get(1) = (%d, %v), want (100, true)", v, ok)
	}
	// Insert a new key: key 2 is now the least recently used and must go.
	c.Put(3, 300)
	if _, ok := c.Get(2); ok {
		t.Errorf("key 2 still present after inserting 3; Get should have refreshed key 1's recency")
	}
	if v, ok := c.Get(1); !ok || v != 100 {
		t.Errorf("Get(1) = (%d, %v), want (100, true)", v, ok)
	}
	if v, ok := c.Get(3); !ok || v != 300 {
		t.Errorf("Get(3) = (%d, %v), want (300, true)", v, ok)
	}
}

func TestPutExistingKeyMarksRecentlyUsed(t *testing.T) {
	c := NewLRUCache(2)
	c.Put(1, 100)
	c.Put(2, 200)
	// Update key 1 so it becomes most recently used.
	c.Put(1, 111)
	// Insert a new key: key 2 is now the least recently used and must go.
	c.Put(3, 300)
	if _, ok := c.Get(2); ok {
		t.Errorf("key 2 still present after inserting 3; Put(1) should have refreshed key 1's recency")
	}
	if v, ok := c.Get(1); !ok || v != 111 {
		t.Errorf("Get(1) = (%d, %v), want (111, true)", v, ok)
	}
}

func TestEvictsLeastRecentlyUsed(t *testing.T) {
	c := NewLRUCache(3)
	c.Put(1, 1)
	c.Put(2, 2)
	c.Put(3, 3)
	c.Get(1) // 1 most recent; 2 least recent
	c.Get(2) // 2 most recent; 3 least recent
	c.Put(4, 4) // evicts 3
	if _, ok := c.Get(3); ok {
		t.Errorf("key 3 still present; it was least recently used")
	}
	for k, want := range map[int]int{1: 1, 2: 2, 4: 4} {
		if v, ok := c.Get(k); !ok || v != want {
			t.Errorf("Get(%d) = (%d, %v), want (%d, true)", k, v, ok, want)
		}
	}
}

func TestGetAbsentKey(t *testing.T) {
	c := NewLRUCache(1)
	if v, ok := c.Get(42); ok || v != 0 {
		t.Errorf("Get(42) = (%d, %v), want (0, false)", v, ok)
	}
}

func TestZeroCapacity(t *testing.T) {
	c := NewLRUCache(0)
	c.Put(1, 100)
	if v, ok := c.Get(1); ok || v != 0 {
		t.Errorf("Get(1) = (%d, %v), want (0, false) for zero-capacity cache", v, ok)
	}
}

